+static void mb_chnl_ack_retry(void)
+{
+	u16 chnl_type = MB_PHY_ACK_CHNL;
+
+	while (1)
+	{
+		mb_ack_entry_t entry;
+		bk_err_t ret;
+		u32 flags = mb_chnl_enter_critical();
